<script setup lang="ts">
import { MenuDivider, MenuGroup, MenuGroupLabel, MenuItem, MenuList, MenuRoot } from '@fex-design/vue/primitive/menu'
import Card from '@fex-design/vue/ui/card'
import { ref } from 'vue'
import { rootClassName, verticalItemClassName, verticalListClassName } from './demo-styles'
const basicOpen = ref(true); const selected = ref('dashboard'); const controlledOpen = ref(true); const controlledSelected = ref('users'); const multiple = ref(new Set(['users', 'articles']))
function toggle(value: string) { const next = new Set(multiple.value); next.has(value) ? next.delete(value) : next.add(value); multiple.value = next }
</script>
<template>
  <Card title="Basic" description="Items, nested children, group, divider and disabled state."><MenuRoot :class="rootClassName"><MenuList :class="verticalListClassName"><MenuItem value="dashboard" :selected="selected === 'dashboard'" :class="verticalItemClassName" @click="selected = 'dashboard'">Dashboard</MenuItem><MenuItem value="system" :class="verticalItemClassName" @click="basicOpen = !basicOpen"><span class="flex-1">System</span><span>{{ basicOpen ? '−' : '+' }}</span></MenuItem><div v-if="basicOpen" class="ml-5"><MenuItem value="users" :selected="selected === 'users'" :class="verticalItemClassName" @click="selected = 'users'">Users</MenuItem><MenuItem value="roles" :selected="selected === 'roles'" :class="verticalItemClassName" @click="selected = 'roles'">Roles</MenuItem><MenuItem value="permissions" disabled :class="verticalItemClassName">Permissions</MenuItem></div><MenuDivider class="my-1 h-px bg-border" /><MenuGroup><MenuGroupLabel class="px-2 py-1 text-xs text-muted-foreground">Workspace</MenuGroupLabel><MenuItem value="settings" :class="verticalItemClassName">Settings</MenuItem><MenuItem value="billing" :class="verticalItemClassName">Billing</MenuItem></MenuGroup></MenuList></MenuRoot></Card>
  <Card title="Controlled" description="Expanded and selected state are owned by the caller."><MenuRoot><MenuList :class="verticalListClassName"><MenuItem value="system" :class="verticalItemClassName" @click="controlledOpen = !controlledOpen"><span class="flex-1">System</span><span>{{ controlledOpen ? 'open' : 'closed' }}</span></MenuItem><div v-if="controlledOpen" class="ml-5"><MenuItem v-for="value in ['users','roles']" :key="value" :value="value" :selected="controlledSelected === value" :class="verticalItemClassName" @click="controlledSelected = value">{{ value }}</MenuItem></div><div class="px-2 pt-2 text-xs text-muted-foreground">expanded: {{ controlledOpen }} · selected: {{ controlledSelected }}</div></MenuList></MenuRoot></Card>
  <Card title="Multiple Selection" description="The caller composes multiple selected items with the same primitive."><MenuRoot><MenuList :class="verticalListClassName"><MenuItem v-for="value in ['users','roles','articles','comments']" :key="value" :value="value" :selected="multiple.has(value)" :class="verticalItemClassName" @click="toggle(value)"><span class="flex-1 capitalize">{{ value }}</span><span>{{ multiple.has(value) ? '✓' : '' }}</span></MenuItem></MenuList></MenuRoot></Card>
  <Card title="Suffix" description="Items accept arbitrary right-side content."><MenuRoot><MenuList :class="verticalListClassName"><MenuItem v-for="item in [['Users','24'],['Comments','8'],['Settings','new']]" :key="item[0]" :value="item[0]" :class="verticalItemClassName"><span class="flex-1">{{ item[0] }}</span><span class="text-xs text-muted-foreground">{{ item[1] }}</span></MenuItem></MenuList></MenuRoot></Card>
  <Card title="Custom Item" description="Slot props bind menu behavior to custom DOM."><MenuRoot><MenuList :class="verticalListClassName"><MenuItem value="profile"><template #trigger="slot"><a v-bind="slot.props" href="#profile" :class="verticalItemClassName"><span class="flex-1">Custom link item</span><span class="text-xs text-primary">open →</span></a></template></MenuItem><MenuItem value="status" :class="verticalItemClassName"><span class="flex-1">Service status</span><span class="text-xs text-muted-foreground">Healthy</span></MenuItem></MenuList></MenuRoot></Card>
</template>
